DIM Punto(0,2) = {{3, 0, 1}}
Angolo = 3.14159 / 4
DIM RotZ(2,2) = {{COS(Angolo),-SIN(Angolo),0},{SIN(Angolo),COS(Angolo),0},{0,0,1}}
Ruotato = MATRIX.MATMUL(Punto, RotZ)
PRINT "Punto (3,0,1) ruotato 45° su Z:"
PRINT "x'=";FORMAT(Ruotato(0,0),"#.00");" y'=";FORMAT(Ruotato(0,1),"#.00");" z'=";FORMAT(Ruotato(0,2),"#.00")
